mapper.select:
SELECT request_payload
FROM capability_invocation
WHERE investigation_id = #{investigationId}
  AND capability_key = #{capabilityKey}
  AND managed_resource_id = #{managedResourceId}
  AND request_schema_name = #{requestSchemaName}
  AND request_schema_version = #{requestSchemaVersion}
  AND (status IN ('PENDING', 'RUNNING') OR finished_at > #{finishedSince})
